// HasEvent applies the HasEdge predicate on the "event" edge.
func HasEvent() predicate.VisitorPlatformClick {
	return predicate.VisitorPlatformClick(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2O, true, EventTable, EventColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasEventWith applies the HasEdge predicate on the "event" edge with a given conditions (other predicates).
func HasEventWith(preds ...predicate.VisitorEvent) predicate.VisitorPlatformClick {
	return predicate.VisitorPlatformClick(func(s *sql.Selector) {
		step := newEventStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.VisitorPlatformClick) predicate.VisitorPlatformClick {
	return predicate.VisitorPlatformClick(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.VisitorPlatformClick) predicate.VisitorPlatformClick {
	return predicate.VisitorPlatformClick(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.VisitorPlatformClick) predicate.VisitorPlatformClick {
	return predicate.VisitorPlatformClick(sql.NotPredicates(p))
}
